import { DomainError } from "./errors";

export class Product {
  private reserved = 0;

  public constructor(
    public readonly id: string,
    public readonly name: string,
    private readonly stock: number,
  ) {
    if (!id.trim() || !name.trim()) {
      throw new DomainError("INVALID_PRODUCT", "A product must have an id and name.");
    }
    if (!Number.isSafeInteger(stock) || stock < 0) {
      throw new DomainError("INVALID_STOCK", "Stock must be a non-negative integer.");
    }
  }

  public get stockLevel(): number {
    return this.stock;
  }

  public get reservedStock(): number {
    return this.reserved;
  }

  public get availableStock(): number {
    return this.stock - this.reserved;
  }

  public reserve(quantity: number): void {
    this.assertQuantity(quantity);
    if (quantity > this.availableStock) {
      throw new DomainError("INSUFFICIENT_STOCK", `Insufficient stock for product ${this.id}.`);
    }
    this.reserved += quantity;
  }

  public release(quantity: number): void {
    this.assertQuantity(quantity);
    if (quantity > this.reserved) {
      throw new DomainError("INVALID_RELEASE", `Cannot release more stock than is reserved for product ${this.id}.`);
    }
    this.reserved -= quantity;
  }

  private assertQuantity(quantity: number): void {
    if (!Number.isSafeInteger(quantity) || quantity <= 0) {
      throw new DomainError("INVALID_QUANTITY", "Quantity must be a positive integer.");
    }
  }
}

